import itertools
import collections

def check_m_efficient(m):
    for residues in itertools.combinations_with_replacement(range(m), m):
        if sum(residues) % m == 0:
            continue

        # Use DP to check if any permutation sum is 0 mod m
        # dp[i][s] = possible multi-sets of residues used
        # Instead, let's use the property that we just need ONE permutation.
        # We can use a recursive function with memoization.

        counts = collections.Counter(residues)
        sorted_res = sorted(counts.keys())
        res_counts = tuple(counts[r] for r in sorted_res)

        memo = {}
        def solve(pos, current_sum, current_counts):
            state = (pos, current_sum, current_counts)
            if state in memo: return memo[state]

            if pos == m + 1:
                return current_sum == 0

            for i, r in enumerate(sorted_res):
                if current_counts[i] > 0:
                    new_counts = list(current_counts)
                    new_counts[i] -= 1
                    if solve(pos + 1, (current_sum + pos * r) % m, tuple(new_counts)):
                        memo[state] = True
                        return True

            memo[state] = False
            return False

        if not solve(1, 0, res_counts):
            return False
    return True

for m in [6, 8, 10, 12, 14, 16]:
    print(f"m={m}: {check_m_efficient(m)}")

import itertools

def check_m_simple(m):
    for residues in itertools.combinations_with_replacement(range(m), m):
        if sum(residues) % m == 0:
            continue
        found_permutation = False
        for p in itertools.permutations(residues):
            if sum((j + 1) * p[j] for j in range(m)) % m == 0:
                found_permutation = True
                break
        if not found_permutation:
            print(f"Counterexample for m={m}: {residues}")
            return False
    return True

print(f"m=6: {check_m_simple(6)}")
